method below_threshold(l: seq<int>, t: int) returns (result: bool)
    requires |l| > 0  // l must not be an empty sequence
    requires forall i :: 0 <= i < |l| ==> l[i] is int  // all elements in l must be integers
    ensures result == (forall i :: 0 <= i < |l| ==> l[i] < t)  // result is True if all elements in l are below t, False otherwise
{
    var i := 0;
    while i < |l|
        invariant 0 <= i <= |l|  // i is within bounds of the sequence
        invariant result == (forall j :: 0 <= j < i ==> l[j] < t)  // result holds for the checked elements
    {
        if l[i] >= t {
            return false;  // If any element is not below threshold, return false
        }
        i := i + 1;  // Move to the next element
    }
    return true;  // All elements are below threshold
}
```

